%[text] %[text:anchor:H_5A7A5B6D] # **Generation of a bilinear quadrilateral mesh**
%[text] It returnd a bilinear quadrilateral mesh for a geometry that is identified by a given set of nodes:
%[text]{"align":"center"} ![bilinear_mesh.png](text:image:38a8)
%[text:tableOfContents]{"heading":"**Table of Contents**"}
function msh = generateBilinearQuadrilateralMesh ...
    (numElx, numEly, numEl, nodesX, nodesY, numNodesEl)
%[text] %[text:anchor:H_D41A3DDC] ## **Function Description**
%[text] It returns a mesh corresponding to bilinear quadrilateral elements.
%[text] %[text:anchor:H_C2A6403E]  **Input :**
%[text]  `numElx`, `numEly` : Number of elements along the $X${"editStyle":"visual"}- and the $Y${"editStyle":"visual"}-directions
%[text]  `numEl` : Total number of elements in the mesh
%[text]  `nodesX`, `nodesY` : $X${"editStyle":"visual"}- and $Y${"editStyle":"visual"}-Cartesian coordinates of the nodes in the mesh
%[text]  `numNodesEl` : Number of nodes per bilinear quadrilateral element
%[text] %[text:anchor:H_CBAFD59D]  **Output :**
%[text]  `msh` : Structure containing the nodes and elements of the mesh
%[text]                                 .`nodes` : Array containing the Cartesian coordinates of the nodes in the mesh
%[text]                            .`elements` : Array containing the node IDs per element in the mesh
%[text] %[text:anchor:H_D5ED9987] ## **Function Implementation**
%[text] %[text:anchor:H_A332AA51] ### Input validation
arguments
    numElx (1, 1) double {mustBeInteger, mustBePositive}
    numEly (1, 1) double {mustBeInteger, mustBePositive}
    numEl (1, 1) double {mustBeInteger, mustBePositive}
    nodesX (:, :) double
    nodesY (:, 1) double {mustHaveEqualNumberOfElements(nodesX, nodesY)}
    numNodesEl (1, 1) double {mustBeInteger, mustBePositive}
end
%[text] %[text:anchor:H_A3159164] ### Check input
if numElx*numEly ~= numEl
    error("The provided number of elements do not match")
end
%[text] %[text:anchor:H_C99D867A] ### Assign the nodes of the quadrilateral bilinear mesh
msh.nodes = [nodesX(:) nodesY zeros(numel(nodesY), 1)];
msh.elements = zeros(numEl, numNodesEl);
counterEl = 1;
for ii = 1:numElx
    adv = (ii - 1)*(numEly + 1);
    advplus1 = ii*(numEly + 1);
    for jj = 1:numEly
        msh.elements(counterEl, :) = [jj+adv jj+adv+1 jj+advplus1+1 jj+advplus1];
        counterEl = counterEl + 1;
    end
end
%[text] 
end

